use core.files as files
use core.process as process
use core.text as text

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    input :: files.read(path) ?? panic("read failed")
    lines :: input.lines()
    section_names := [String]{}
    section_inherits := [String]{}
    field_sections := [String]{}
    field_keys := [String]{}
    field_values := [String]{}
    current := ""

    loop line in lines {
        clean :: ~(line.trim())
        if clean.is_empty() -> next
        if clean.contains("=") {
            pieces :: text.splitn(clean, "=", 2)
            if pieces.len() != 2 -> panic("malformed field")
            key :: (pieces.get(0) ?? panic("malformed field")).trim()
            raw :: (pieces.get(1) ?? panic("malformed field")).trim()
            if current.is_empty() -> panic("field before section")
            if key.is_empty() -> panic("malformed field")
            quoted :: text.splitn(raw, "\"", 3)
            if quoted.len() != 3 -> panic("malformed value")
            if (quoted.get(0) ?? panic("malformed value")) != "" -> panic("malformed value")
            if (quoted.get(2) ?? panic("malformed value")) != "" -> panic("malformed value")
            value :: quoted.get(1) ?? panic("malformed value")
            duplicate := false
            i := 0
            loop i < field_sections.len() {
                if field_sections[i] == current && field_keys[i] == key {
                    duplicate = true
                    break
                }
                i += 1
            }
            if duplicate -> panic("duplicate field {key} in section [{current}]")
            field_sections.push(~current)
            field_keys.push(~key)
            field_values.push(~value)
            if key == "inherits" {
                h := 0
                loop h < section_names.len() {
                    if section_names[h] == current {
                        section_inherits[h] = ~value
                        break
                    }
                    h += 1
                }
            }
        } else if clean.contains("[") {
            header :: text.splitn(clean, "[", 2)
            if header.len() != 2 -> panic("malformed section")
            rest :: header.get(1) ?? panic("malformed section")
            name_parts :: text.splitn(rest, "]", 2)
            if name_parts.len() != 2 -> panic("malformed section")
            if (name_parts.get(1) ?? panic("malformed section")) != "" -> panic("malformed section")
            section_name :: (name_parts.get(0) ?? panic("malformed section")).trim()
            if section_name.is_empty() -> panic("malformed section")
            section_names.push(~section_name)
            section_inherits.push("")
            current = ~section_name
        } else -> panic("malformed line")
    }

    s := 0
    loop s < section_names.len() {
        section :: section_names[s]
        parent :: section_inherits[s]
        resolved_keys := [String]{}
        resolved_values := [String]{}
        if !parent.is_empty() {
            p := 0
            loop p < section_names.len() {
                if section_names[p] == parent -> break
                p += 1
            }
            if p == section_names.len() -> panic("unknown parent section [{parent}]")
            f := 0
            loop f < field_sections.len() {
                if field_sections[f] == parent && field_keys[f] != "inherits" {
                    parent_key :: field_keys[f]
                    own_found := false
                    own_value := ""
                    o := 0
                    loop o < field_sections.len() {
                        if field_sections[o] == section && field_keys[o] == parent_key {
                            own_found = true
                            own_value = ~field_values[o]
                            break
                        }
                        o += 1
                    }
                    resolved_keys.push(~parent_key)
                    if own_found -> resolved_values.push(~own_value) else -> resolved_values.push(~field_values[f])
                }
                f += 1
            }
        }
        f := 0
        loop f < field_sections.len() {
            if field_sections[f] == section && field_keys[f] != "inherits" {
                key :: field_keys[f]
                inherited := false
                o := 0
                loop o < resolved_keys.len() {
                    if resolved_keys[o] == key {
                        inherited = true
                        break
                    }
                    o += 1
                }
                if !inherited {
                    resolved_keys.push(~key)
                    resolved_values.push(~field_values[f])
                }
            }
            f += 1
        }
        o := 0
        loop o < resolved_keys.len() {
            print("{section}.{resolved_keys[o]}={resolved_values[o]}")
            o += 1
        }
        s += 1
    }
}
